202	TEST(DynamicUnlockingTest, HeldLocksMissingFromSnapshot_DoesNotAffectOwnedReleaseSet) {
203	  // 快照中根本没有的锁 id 不会凭空出现（释放集只来自路径推导 ∩ 实际持有）
204	  auto held = BuildHeld({NodeLock("station_a"), EdgeLock("station_a", "station_b")});
205	
206	  const auto decision = PlanTrailingUnlock(kPath, "station_c", 4, kMission, held);
207	
208	  EXPECT_TRUE(decision.confirmed);
209	  // k=2 理论释放 {node_a, edge_ab, node_b}，但 held 中没有 node_b -> 只返回实际持有的两个
210	  ASSERT_EQ(decision.lock_ids_to_release.size(), 2U);
