215	// ---------------- Rule 1：ResourceTable 部分释放（幂等 + 所有权） ----------------
216	
217	TEST(DynamicUnlockingTest, Idempotency_RecomputeAfterPartialRelease_YieldsNothingLeft) {
218	  ResourceTable table;
219	  const auto all_locks = AllPathLocks(kPath);
220	  ASSERT_TRUE(table.Reserve(kMission, all_locks).success);
221	
222	  // 第一次计算：k=2 应释放身后 3 把锁
223	  auto held = BuildHeld(all_locks);
224	  const auto first = PlanTrailingUnlock(kPath, "station_c", 4, kMission, held);
225	  ASSERT_TRUE(first.confirmed);
226	  ASSERT_EQ(first.lock_ids_to_release.size(), 3U);
227	
228	  const auto released = table.ReleaseResources(kMission, first.lock_ids_to_release);
229	  EXPECT_EQ(released.size(), 3U);
230	
231	  // 第二次计算：输入完全相同（小车重复上报），但足迹锁仍在、身后锁已不持有
232	  std::unordered_map<std::string, std::string> snapshot_held;
233	  for (const auto& [resource_id, owner] : table.Snapshot()) {
234	    snapshot_held[resource_id] = owner;
235	  }
236	  const auto second = PlanTrailingUnlock(kPath, "station_c", 4, kMission, snapshot_held);
237	  EXPECT_TRUE(second.confirmed);
238	  EXPECT_TRUE(second.lock_ids_to_release.empty());  // 无剩余可释放 -> 幂等
239	
240	  // 足迹锁仍被本任务持有
241	  EXPECT_TRUE(table.Locked(NodeLock("station_c")));
242	  EXPECT_TRUE(table.Locked(EdgeLock("station_b", "station_c")));
243	  EXPECT_TRUE(table.Locked(EdgeLock("station_c", "station_d")));
244	
245	  // 对已释放 id 再次部分释放是安全 no-op
246	  EXPECT_TRUE(table.ReleaseResources(kMission, first.lock_ids_to_release).empty());
247	}
