ep.manufacturer = manufacturer;  // manufacturer 以首见为准，保证后续原路回发
if (!IsValidVehicleId(vehicle_id)) {
  RCLCPP_ERROR(get_logger(),
               "serialNumber '%s' 不是合法 ROS 话题段（须字母或 '_' 开头，仅含字母/数字/'_'），"
               "跳过该车全部 ROS 端点创建（MQTT 订阅解析不受影响）",
